    <button type="button" class="site-menu-toggle" id="site-menu-toggle" aria-expanded="false" aria-controls="site-navigation" aria-label="Navigation principale"><svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false"><path d="M4 6h16M4 12h16M4 18h16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button>
