function plainBody(container,value){
  var paragraph=[],list=null,listType=null;
  function flush(){if(paragraph.length){container.append(el('p','',paragraph.join(' ')));paragraph=[]}list=null;listType=null}
  String(value||'').replace(/\r/g,'').split('\n').forEach(function(line){
    var heading=line.match(/^(#{1,3})\s+(.+)$/),bullet=line.match(/^\s*[-*]\s+(.+)$/),ordered=line.match(/^\s*\d+\.\s+(.+)$/);
    if(!line.trim()){flush();return}
    if(heading){flush();container.append(el(heading[1].length<3?'h2':'h3','',heading[2]));return}
    if(/^\s*---+\s*$/.test(line)){flush();container.append(el('hr'));return}
    if(bullet||ordered){if(paragraph.length)flush();var type=bullet?'ul':'ol';if(!list||listType!==type){list=el(type);listType=type;container.append(list)}list.append(el('li','',(bullet||ordered)[1]));return}
    if(list){list=null;listType=null}paragraph.push(line.trim());
  });flush();
}
